function extractAddress(value) {
  if (!value) return { name: '', email: '' };
  if (typeof value === 'object' && Array.isArray(value.value) && value.value[0]) {
    return { name: value.value[0].name || '', email: value.value[0].address || '' };
  }
  const text = String(value.text || value);
  const match = text.match(/^(.*?)\s*<([^>]+)>$/);
  return match ? { name: match[1].trim().replace(/^\"|\"$/g, ''), email: match[2].trim() } : { name: '', email: text.trim() };
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

const sender = extractAddress($json.from);
let body = $json.text || $json.textPlain || htmlToText($json.html || $json.textHtml || '');
body = String(body)
  .replace(/\r/g, '')
  .split(/\n(?:On .+ wrote:|Dana .+ napisao je:|From:|Od:|-----Original Message-----)/i)[0]
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 12000);

return {
  json: {
    message_id: $json.id,
    thread_id: $json.threadId,
    sender_name: sender.name,
    sender_email: sender.email,
    subject: String($json.subject || '(bez naslova)').slice(0, 500),
    received_at: $json.date || '',
    body
  }
};

