const confidence = Math.max(0, Math.min(1, Number($json.confidence || 0)));
const draft = String($json.draft || '').trim();
const shouldCreateDraft = $json.needs_reply === true && confidence >= 0.80 && draft.length > 0;
const calendarProposal = $json.has_calendar_item === true
  ? { title: String($json.event_title || ''), start: String($json.event_start || ''), end: String($json.event_end || ''), timezone: String($json.event_timezone || 'Europe/Zagreb') }
  : null;

return {
  json: {
    ...$json,
    confidence,
    draft,
    should_create_draft: shouldCreateDraft,
    calendar_proposal: calendarProposal,
    outcome: shouldCreateDraft ? 'SKICA' : 'SAZETAK',
    processed_at: new Date().toISOString()
  }
};

const rows = Array.isArray($json.items) ? $json.items : [];
const date = new Intl.DateTimeFormat('hr-HR', { timeZone: 'Europe/Zagreb', dateStyle: 'full' }).format(new Date());
const lines = [`Jutarnji pregled pošte - ${date}`, '', `Obrađeno poruka: ${rows.length}`, ''];
for (const [index, row] of rows.entries()) {
  lines.push(`${index + 1}. [${String(row.priority || 'normal').toUpperCase()}] ${row.subject || '(bez naslova)'}`);
  lines.push(`   Od: ${row.sender_name || ''} <${row.sender_email || ''}>`);
  lines.push(`   Ishod: ${row.outcome === 'SKICA' ? 'napravljena skica za provjeru' : 'samo sažetak'}`);
  lines.push(`   Sažetak: ${row.summary || ''}`);
  lines.push(`   Razlog: ${row.reason || ''} (pouzdanost ${Number(row.confidence || 0).toFixed(2)})`);
  if (row.calendar_proposal) {
    lines.push(`   Kalendar - prijedlog, nije automatski upisan: ${row.calendar_proposal.title || ''}; ${row.calendar_proposal.start || 'vrijeme nije pouzdano određeno'}; ${row.calendar_proposal.timezone || 'Europe/Zagreb'}`);
  }
  lines.push('');
}
return { json: { subject: `AI jutarnji pregled - ${date}`, body: lines.join('\n') } };
